#include <type_traits>

struct A {
    enum E {};
};
static_assert(std::is_enum_v<A> == false);
static_assert(std::is_enum_v<A::E> == true);

enum E {};
static_assert(std::is_enum_v<E> == true);

enum class Ec : int {};
static_assert(std::is_enum_v<Ec> == true);

static_assert(std::is_enum_v<int> == false);

int main() {}
